SELECT pg_advisory_xact_lock(839472521);
CREATE TABLE IF NOT EXISTS "Suppliers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CompanyKey" varchar(64) NOT NULL DEFAULT 'fti-demo' REFERENCES "CompanyProfiles" ("Key") ON DELETE RESTRICT,
    "Name" varchar(200) NOT NULL,
    "NormalizedName" varchar(200) NOT NULL,
    "ContactName" varchar(150) NOT NULL,
    "Email" varchar(254) NOT NULL,
    "Phone" varchar(50) NOT NULL,
    "Notes" varchar(1000) NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreationToken" uuid NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Suppliers_CompanyKey_NormalizedName" ON "Suppliers" ("CompanyKey","NormalizedName");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Suppliers_CompanyKey_CreationToken" ON "Suppliers" ("CompanyKey","CreationToken");
CREATE TABLE IF NOT EXISTS "ProductSuppliers" (
    "ProductId" integer NOT NULL REFERENCES "Products" ("Id") ON DELETE RESTRICT,
    "SupplierId" integer NOT NULL REFERENCES "Suppliers" ("Id") ON DELETE RESTRICT,
    "CompanyKey" varchar(64) NOT NULL DEFAULT 'fti-demo' REFERENCES "CompanyProfiles" ("Key") ON DELETE RESTRICT,
    "IsDefault" boolean NOT NULL,
    PRIMARY KEY ("ProductId","SupplierId")
);
CREATE INDEX IF NOT EXISTS "IX_ProductSuppliers_SupplierId" ON "ProductSuppliers" ("SupplierId");
CREATE INDEX IF NOT EXISTS "IX_ProductSuppliers_CompanyKey" ON "ProductSuppliers" ("CompanyKey");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_ProductSuppliers_Default" ON "ProductSuppliers" ("ProductId") WHERE "IsDefault";
ALTER TABLE "Replenishments" ADD COLUMN IF NOT EXISTS "SupplierId" integer REFERENCES "Suppliers" ("Id") ON DELETE RESTRICT;
CREATE INDEX IF NOT EXISTS "IX_Replenishments_SupplierId" ON "Replenishments" ("SupplierId");
INSERT INTO "SchemaUpdates" ("Name") VALUES ('009-product-suppliers') ON CONFLICT DO NOTHING;
